#!/usr/bin/env node
// Generates the evidence model from its single source, contracts/evidence.openapi.yaml:
//   - TS types with openapi-typescript (packages/protocol/src/evidence.gen.ts);
//   - Go models with oapi-codegen, models only (apps/server/internal/store/evidence_models_generated.go);
//   - the JSON Schema 2020-12 bundle both validators load (Ajv in TS, jsonschema/v6 in Go).
// The code here is glue only: it adapts the document for each generator and formats the output.
//
//   node scripts/generate-evidence-models.mjs                 write the generated files
//   node scripts/generate-evidence-models.mjs --check         fail on a stale file or a breaking change
//   node scripts/generate-evidence-models.mjs --check --base <git rev | file>
//
// The breaking-change check (oasdiff) compares the document with the one at the merge base of
// HEAD and origin/main (or HEAD). Acknowledge an intended break in contracts/oasdiff-err-ignore.txt.
import { execFileSync, spawnSync } from "node:child_process";
import {
  existsSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import prettier from "prettier";
import ts from "typescript";

// Pinned Go tools, run with `go run module@version` (verified against the Go checksum database).
const oapiCodegen =
  "github.com/oapi-codegen/oapi-codegen/v2/cmd/oapi-codegen@v2.8.2";
const oasdiff = "github.com/oasdiff/oasdiff@v1.35.0";
const goTool = (tool, toolArgs, options) =>
  spawnSync("go", ["run", tool, ...toolArgs], { encoding: "utf8", ...options });

const root = resolve(import.meta.dirname, "..");
const contract = "contracts/evidence.openapi.yaml";
const fromProtocol = createRequire(
  resolve(root, "packages/protocol/package.json"),
);
const { parse, stringify } = fromProtocol("yaml");
const openapiTS = fromProtocol("openapi-typescript");
const tsVersion = fromProtocol("openapi-typescript/package.json").version;

const args = process.argv.slice(2);
const check = args.includes("--check");
const base = args.includes("--base") ? args[args.indexOf("--base") + 1] : "";
const doc = parse(readFileSync(resolve(root, contract), "utf8"));
const schemas = doc.components.schemas;
const refName = (ref) => ref.slice("#/components/schemas/".length);
const unions = Object.keys(schemas).filter(
  (name) => schemas[name].oneOf && schemas[name].discriminator,
);
const banner = (tool) =>
  `Code generated by scripts/generate-evidence-models.mjs from ${contract} (${tool}); DO NOT EDIT.`;

async function format(text, path) {
  const options = await prettier.resolveConfig(resolve(root, path));
  return prettier.format(text, { ...options, filepath: path });
}

// TS: openapi-typescript with root type aliases (`export type IssueContract = ...`). Only the
// named schema types are exported; `components` stays module-private.
async function typescript() {
  // The recursive JSONValue is one named alias: openapi-typescript's inline form
  // `components["schemas"]["JSONValue"][]` is rejected by tsc (TS2502).
  const jsonValue =
    "null | boolean | number | string | JSONValue[] | { [key: string]: JSONValue }";
  const ast = await openapiTS.default(structuredClone(doc), {
    transform(_schema, options) {
      if (options.path === "#/components/schemas/JSONValue")
        return ts.factory.createTypeReferenceNode("JSONValue");
    },
  });
  // Keep only `components`, unexported; export one alias per schema under its own name.
  const components = ast.find(
    (node) =>
      ts.isInterfaceDeclaration(node) && node.name.text === "components",
  );
  const aliases = Object.keys(schemas)
    .map(
      (name) =>
        `export type ${name} = ${name === "JSONValue" ? jsonValue : `components["schemas"]["${name}"]`};`,
    )
    .join("\n");
  return format(
    `// ${banner(`openapi-typescript ${tsVersion}`)}\n` +
      openapiTS
        .astToString([components])
        .replace(/^export interface components/m, "interface components") +
      aliases +
      "\n",
    "packages/protocol/src/evidence.gen.ts",
  );
}

// JSON Schema 2020-12: the components as $defs, without OpenAPI-only keywords (x-*, the
// numeric `format` registry, discriminator mappings). Ajv keys unions on `discriminator`.
async function jsonSchema() {
  const oasFormats = new Set(["int32", "int64", "float", "double"]);
  const convert = (value) => {
    if (Array.isArray(value)) return value.map(convert);
    if (!value || typeof value !== "object") return value;
    return Object.fromEntries(
      Object.entries(value)
        .filter(([key]) => !key.startsWith("x-"))
        .filter(([key, v]) => !(key === "format" && oasFormats.has(v)))
        .map(([key, v]) =>
          key === "$ref"
            ? [key, `#/$defs/${refName(v)}`]
            : key === "discriminator"
              ? [key, { propertyName: v.propertyName }]
              : [key, convert(v)],
        ),
    );
  };
  return format(
    JSON.stringify({
      $comment: banner("JSON Schema bundle"),
      $schema: "https://json-schema.org/draft/2020-12/schema",
      $defs: convert(schemas),
    }),
    "packages/protocol/src/evidence-schema.json",
  );
}

// Go: oapi-codegen generates plain structs that keep today's Go API. The document is adapted
// first: allOf is flattened (inherited fields first), each union becomes one struct with the
// fields of all its variants (its MarshalJSON is appended below), enums stay plain Go strings,
// field names follow the existing ID/IDs/URI convention, and x-order keeps declaration order.
function goDocument() {
  const source = structuredClone(schemas);
  const deref = (s) => (s.$ref ? source[refName(s.$ref)] : s);
  const object = (parts) => {
    const properties = {};
    for (const part of parts)
      for (const [key, value] of Object.entries(part.properties ?? {}))
        properties[key] ??= value;
    return { type: "object", properties };
  };
  const flat = (s) => {
    if (!s.allOf) return s;
    const parts = s.allOf.map((p) => flat(deref(p)));
    return {
      ...object(parts),
      required: parts.flatMap((p) => p.required ?? []),
    };
  };
  const out = {};
  for (const [name, s] of Object.entries(source)) out[name] = flat(s);
  // Any JSON value; its `null` branch would otherwise make map values pointers.
  out.JSONValue = { "x-go-type": "any" };
  for (const name of unions) {
    const variants = source[name].oneOf.map(deref);
    out[name] = {
      ...object(variants),
      required: variants
        .map((v) => v.required)
        .reduce((a, b) => a.filter((k) => b.includes(k))),
    };
    for (const v of source[name].oneOf) delete out[refName(v.$ref)];
  }
  const goName = (s) =>
    s
      .replace(/(^|_)(\w)/g, (_, _p, c) => c.toUpperCase())
      .replace(/Id(s?)$/g, "ID$1")
      .replace(/Uri$/, "URI");
  const adapt = (s) => {
    if (!s || typeof s !== "object") return;
    delete s.enum;
    Object.entries(s.properties ?? {}).forEach(([key, p], i) => {
      p["x-go-name"] = goName(key);
      p["x-order"] = i + 1;
      adapt(p);
    });
    adapt(s.items);
    if (typeof s.additionalProperties === "object")
      adapt(s.additionalProperties);
  };
  Object.values(out).forEach(adapt);
  return { ...doc, paths: {}, components: { schemas: out } };
}

function go() {
  const dir = mkdtempSync(join(tmpdir(), "fdy-evidence-go-"));
  try {
    writeFileSync(join(dir, "evidence.yaml"), stringify(goDocument()));
    writeFileSync(
      join(dir, "config.yaml"),
      stringify({
        package: "store",
        generate: { models: true },
        "output-options": {
          "skip-prune": true,
          "prefer-skip-optional-pointer-on-container-types": true,
        },
      }),
    );
    const result = goTool(
      oapiCodegen,
      ["-config", "config.yaml", "evidence.yaml"],
      { cwd: dir },
    );
    if (result.status !== 0)
      throw new Error(`oapi-codegen failed:\n${result.stderr}`);
    const body = result.stdout
      .slice(result.stdout.indexOf("package store"))
      .replace("package store", 'package store\n\nimport "encoding/json"');
    // A union is encoded with the required arrays and maps of its variant, never null.
    const marshal = unions.map(
      (name) => `
func (v ${name}) MarshalJSON() ([]byte, error) {
	type plain ${name}
	raw, err := json.Marshal(plain(v))
	if err != nil {
		return nil, err
	}
	return marshalEvidenceUnion("${name}", v.Kind, raw)
}`,
    );
    return execFileSync("gofmt", {
      input: `// ${banner(`oapi-codegen ${oapiCodegen.split("@")[1]}`)}\n\n${body}${marshal.join("\n")}\n`,
      encoding: "utf8",
    });
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

// oasdiff only diffs schemas that operations reach. Stored records are both written and read,
// so each model no other schema refers to gets one synthetic operation with it as request
// and response; everything else is reached through them.
function withStorageOperations(spec) {
  const copy = structuredClone(spec);
  const referenced = new Set(
    [
      ...JSON.stringify(copy.components.schemas).matchAll(
        /"#\/components\/schemas\/(\w+)"/g,
      ),
    ].map((match) => match[1]),
  );
  copy.paths = Object.fromEntries(
    Object.keys(copy.components.schemas)
      .filter((name) => !referenced.has(name))
      .map((name) => {
        const content = {
          "application/json": {
            schema: { $ref: `#/components/schemas/${name}` },
          },
        };
        return [
          `/x-storage/${name}`,
          {
            post: {
              operationId: `store${name}`,
              requestBody: { required: true, content },
              responses: { 200: { description: "Stored", content } },
            },
          },
        ];
      }),
  );
  return copy;
}

function git(...gitArgs) {
  const result = spawnSync("git", gitArgs, { cwd: root, encoding: "utf8" });
  return result.status === 0 ? result.stdout.trim() : undefined;
}

function breakingChanges() {
  const against =
    base ||
    git("merge-base", "HEAD", "origin/main") ||
    git("rev-parse", "HEAD");
  const previous = existsSync(resolve(against))
    ? readFileSync(resolve(against), "utf8")
    : git("show", `${against}:${contract}`);
  if (!previous) {
    console.log(
      `evidence contract: no ${contract} at ${against}; breaking-change check skipped`,
    );
    return true;
  }
  const dir = mkdtempSync(join(tmpdir(), "fdy-evidence-oasdiff-"));
  try {
    const write = (name, spec) => {
      writeFileSync(join(dir, name), stringify(withStorageOperations(spec)));
      return join(dir, name);
    };
    const result = goTool(
      oasdiff,
      [
        "breaking",
        write("base.yaml", parse(previous)),
        write("revision.yaml", doc),
        "--severity-levels",
        resolve(root, "contracts/oasdiff-severity.txt"),
        "--err-ignore",
        resolve(root, "contracts/oasdiff-err-ignore.txt"),
        "--flatten-allof",
        "--fail-on",
        "ERR",
        "--color",
        "never",
      ],
      { cwd: dir },
    );
    if (result.status !== 0) {
      console.error(
        `evidence contract: breaking changes against ${against} (acknowledge intended ones in contracts/oasdiff-err-ignore.txt):\n${result.stdout}${result.stderr}`,
      );
      return false;
    }
    console.log(`evidence contract: no breaking changes against ${against}`);
    return true;
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

const schemaJSON = await jsonSchema();
const outputs = [
  ["packages/protocol/src/evidence.gen.ts", await typescript()],
  ["packages/protocol/src/evidence-schema.json", schemaJSON],
  ["apps/server/internal/store/evidence-schema.json", schemaJSON],
  ["apps/server/internal/store/evidence_models_generated.go", go()],
];
let ok = true;
for (const [name, content] of outputs) {
  const path = resolve(root, name);
  if (!check) writeFileSync(path, content);
  else if (readFileSync(path, "utf8") !== content) {
    console.error(`Stale generated file: ${name} (run pnpm generate:evidence)`);
    ok = false;
  }
}
if (check) ok = breakingChanges() && ok;
if (!ok) process.exit(1);
